//! What GetLocaleInfo says of each locale of the built-in Windows: its
//! language's and country's names, and the formats of its numbers, money,
//! dates and times; each locale's ids and code pages (`LOCALES`); and the
//! values of the `win32_locale` setting (`Win32Locale`). The text is
//! Unicode here; GetLocaleInfoA gives it in the locale's code page.
//!
//! Generated by tools/gen_locales.py from tools/locales.txt, which says
//! where the values come from. Change that file, not this one.
//!
//! The names of the language and the country (LOCALE_SLANGUAGE and
//! LOCALE_SCOUNTRY) are the English ones, as an English Windows shows
//! them; a localized Windows shows them in its own language.

use super::{
    ANSI_CHARSET, BALTIC_CHARSET, EASTEUROPE_CHARSET, GREEK_CHARSET, RUSSIAN_CHARSET,
    TURKISH_CHARSET,
};
use super::{Locale, locale};

/// A locale's information.
pub struct Info {
    /// LOCALE_SLANGUAGE, LOCALE_SENGLANGUAGE, LOCALE_SABBREVLANGNAME,
    /// LOCALE_SNATIVELANGNAME and LOCALE_SISO639LANGNAME.
    pub full_language: &'static str,
    pub language: &'static str,
    pub abbrev_language: &'static str,
    pub native_language: &'static str,
    pub iso_language: &'static str,
    /// LOCALE_SENGCOUNTRY, LOCALE_SABBREVCTRYNAME, LOCALE_SNATIVECTRYNAME
    /// and LOCALE_SISO3166CTRYNAME.
    pub country: &'static str,
    pub abbrev_country: &'static str,
    pub native_country: &'static str,
    pub iso_country: &'static str,
    /// LOCALE_SLIST and LOCALE_IMEASURE (0 metric, 1 US).
    pub list: &'static str,
    pub measure: &'static str,
    /// Numbers: LOCALE_SDECIMAL, LOCALE_STHOUSAND, LOCALE_SGROUPING and
    /// LOCALE_INEGNUMBER.
    pub decimal: &'static str,
    pub thousand: &'static str,
    pub grouping: &'static str,
    pub negative_number: &'static str,
    /// Money: LOCALE_SCURRENCY, LOCALE_SINTLSYMBOL, LOCALE_SMONDECIMALSEP,
    /// LOCALE_SMONTHOUSANDSEP, LOCALE_ICURRENCY and LOCALE_INEGCURR.
    pub currency: &'static str,
    pub intl_symbol: &'static str,
    pub money_decimal: &'static str,
    pub money_thousand: &'static str,
    pub currency_order: &'static str,
    pub negative_currency: &'static str,
    /// Dates and times: LOCALE_SDATE, LOCALE_STIME, LOCALE_SSHORTDATE,
    /// LOCALE_SLONGDATE, LOCALE_STIMEFORMAT, LOCALE_IDATE (0 MDY, 1 DMY,
    /// 2 YMD), LOCALE_ITIME (0 12 hours, 1 24), LOCALE_S1159,
    /// LOCALE_S2359 and LOCALE_IFIRSTDAYOFWEEK (0 Monday, 6 Sunday).
    pub date_separator: &'static str,
    pub time_separator: &'static str,
    pub short_date: &'static str,
    pub long_date: &'static str,
    pub time_format: &'static str,
    pub date_order: &'static str,
    pub hours24: &'static str,
    pub am: &'static str,
    pub pm: &'static str,
    pub first_day: &'static str,
    /// The days from Monday, and the months, and their abbreviations.
    pub days: [&'static str; 7],
    pub abbrev_days: [&'static str; 7],
    pub months: [&'static str; 12],
    pub abbrev_months: [&'static str; 12],
}

/// The system locale of the built-in Windows (`win32_locale`): the
/// localized Windows 98 it is, which sets its ANSI and OEM code pages,
/// its locale's information and formats, and its fonts' character set.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Hash)]
pub enum Win32Locale {
    /// English (United States), United States: code pages 1252 and 437.
    #[default]
    EnUs,
    /// Russian, Russia: code pages 1251 and 866.
    RuRu,
    /// Polish, Poland: code pages 1250 and 852.
    PlPl,
    /// Czech, Czech Republic: code pages 1250 and 852.
    CsCz,
    /// Hungarian, Hungary: code pages 1250 and 852.
    HuHu,
    /// Greek, Greece: code pages 1253 and 737.
    ElGr,
    /// Turkish, Turkey: code pages 1254 and 857.
    TrTr,
    /// Lithuanian, Lithuania: code pages 1257 and 775.
    LtLt,
    /// Latvian, Latvia: code pages 1257 and 775.
    LvLv,
    /// Estonian, Estonia: code pages 1257 and 775.
    EtEe,
    /// Belarusian, Belarus: code pages 1251 and 866.
    BeBy,
    /// Bulgarian, Bulgaria: code pages 1251 and 866.
    BgBg,
    /// Serbian (Cyrillic), Yugoslavia: code pages 1251 and 855.
    SrCyrlYu,
    /// Ukrainian, Ukraine: code pages 1251 and 866.
    UkUa,
    /// Croatian, Croatia: code pages 1250 and 852.
    HrHr,
    /// Romanian, Romania: code pages 1250 and 852.
    RoRo,
    /// Serbian (Latin), Yugoslavia: code pages 1250 and 852.
    SrLatnYu,
    /// Slovak, Slovakia: code pages 1250 and 852.
    SkSk,
    /// Slovenian, Slovenia: code pages 1250 and 852.
    SlSi,
    /// Danish, Denmark: code pages 1252 and 850.
    DaDk,
    /// German (Standard), Germany: code pages 1252 and 850.
    DeDe,
    /// English (United Kingdom), United Kingdom: code pages 1252 and 850.
    EnGb,
    /// Spanish (Traditional Sort), Spain: code pages 1252 and 850.
    EsEs,
    /// Finnish, Finland: code pages 1252 and 850.
    FiFi,
    /// French (Standard), France: code pages 1252 and 850.
    FrFr,
    /// Italian (Standard), Italy: code pages 1252 and 850.
    ItIt,
    /// Norwegian (Bokmål), Norway: code pages 1252 and 850.
    NbNo,
    /// Dutch (Standard), Netherlands: code pages 1252 and 850.
    NlNl,
    /// Portuguese (Brazilian), Brazil: code pages 1252 and 850.
    PtBr,
    /// Portuguese (Standard), Portugal: code pages 1252 and 850.
    PtPt,
    /// Swedish, Sweden: code pages 1252 and 850.
    SvSe,
}

